function RelationshipEngine(npc, action, step2) {
  const DEF = Object.freeze({
    EXPLICIT: "EXPLICIT-ONLY. MUST be stated in Character Card / Lore / Scene text / tracker. NO inference. Uncertain = N. FIRST YES = FINAL CHOICE",
    GET_STATS: "getStats(npc): scan MOST RECENT sceneTracker() ==NPCs== → Present/Absent for exact NPC name; read 'currentSocialDisposition: B[x]/F[x]/H[x]'. If valid 1-4 → {B:x,F:y,H:z}; else null. EXPLICIT-ONLY.",
    FEAR_IMMUNITY: "EXPLICIT-ONLY in card/lore/scene/tracker: NPC impervious to fear/mental manipulation OR same/superior race as user. Uncertain=N.",
    INTIMACY_OVERRIDE: "intimacyOverrideExplicit returns one tag ONLY if explicit in card/lore/scene/tracker: Transactional=sex worker/paid arrangement/contract/client. Hedonist=promiscuous/hedonist/open to fun/intimacy/NSFW welcomed/stated willingness/invites. Exploitation=desperation/coercion/leverage/hostage terms/naive/innocent/manipulation. Established=spouse/lover/dating/prior sex/ongoing affair/'we've done this before'. Uncertain=NONE.",
    BANDS: "BOND(B):1 avoid/leave/ignore. 2 neutral/transactional. 3 cooperative/comfortable; shares surface info; NO intimacy. 4 close/trusting; shares sensitive info; allows closeness/touch; intimacy possible. FEAR(F):1 unshaken. 2 alert. 3 FREEZE: avoids escalation; backs off; defers/complies. 4 TERROR: flight/surrender/calls help; drops objectives. HOSTILITY(H):1 warm/loyal. 2 neutral. 3 FREEZE: obstructs; insults/threatens; sets conditions. 4 HATRED: seeks harm/ruin; escalates; attacks/sabotages/recruits. INTERNAL CONFLICT when F>2 or H>2: delays, half-steps, cut-off speech, restrained movements (no trope physiology).",
    CONSENT: "CONSENT=Y ONLY if explicit affirmative consent is present in-scene or established beforehand. Roll success, attraction, teasing, or silence does NOT equal consent. Uncertain = N.",
    RISK: "RISK=Y ONLY if concrete STAKES are present in THIS scene for {{user}} (FIRST-YES-WINS): Safety (injury/death/capture/restraint; includes immediate escalation risk from an on-scene threat), Resources (money/items/time), Status (reputation/authority/trust/legal trouble), Detection (exposure/stealth/secrecy), Outcome (success/failure of a goal/objective). Must be based on observable facts, NOT tone/vibes/personality guesses. Uncertain = N.",
    NPC_STAKES: "NPC_STAKES=Y ONLY if concrete scene facts show {{user}}'s act could protect/relieve/benefit THIS NPC (block attack, create exit, stop harassment, remove threat, call authority where consequences are established). No vibe. Uncertain = N."
  });

  function getStats(npc) { /* DEF.GET_STATS */ return null; }

  const fearImmuneExplicit = () => false;             // DEF.FEAR_IMMUNITY
  const consentExplicit = () => false;                // DEF.CONSENT
  const intimacyOverrideExplicit = () => "NONE";      // DEF.INTIMACY_OVERRIDE
  const riskExplicit = () => false;                   // DEF.RISK
  const impactOnNpcExplicit = (npc, step2) => "NONE"; // DEF.NPC_STAKES ("BENEFIT"|"HARM"|"NONE")

  const userNonTypical = () => false;
  const userBadRep = () => false;
  const npcAuthority = () => false;
  const userGoodRep = () => false;

  function initPreset() {
    // LOCKED FIRST-YES-WINS EXPLICIT-ONLY
    // Used only when getStats(npc) is null.
    // First impression only; current-scene opposition does NOT initialize hostility by itself.
    // userGoodRep -> {B:3,F:1,H:2}
    // userNonTypical && !fearImmune -> {B:2,F:3,H:2}
    // userBadRep && npcAuthority -> {B:1,F:2,H:3}
    // else neutral -> {B:2,F:2,H:2}
    if (userGoodRep()) return { B: 3, F: 1, H: 2 };
    if (userNonTypical() && !fearImmuneExplicit()) return { B: 2, F: 3, H: 2 };
    if (userBadRep() && npcAuthority()) return { B: 1, F: 2, H: 3 };
    return { B: 2, F: 2, H: 2 };
  }

function isInteractionRelevant(npc, step2) {
  const direct = step2.ActionTargets.includes(npc.name);
  const opposed = step2.OppTargets.includes(npc.name);
  const observer = step2.AffectedObservers.includes(npc.name);
  return direct || opposed || observer;
}

  const relevant = isInteractionRelevant(npc, step2);
  const stats = relevant ? (getStats(npc) || initPreset()) : null;

if (!relevant) {
  return {
    NPC: npc.name,
    FinalState: "UNINITIALIZED",
    Lock: "None",
    Behavior: "None",
    Target: "No Change",
    Landed: step2.LandedActions > 0 ? "Y" : "N",
    OutcomeTier: step2.OutcomeTier || "NONE",
    NarrationBand: step2.NarrationBand || "standard",
    IntimacyGate: "SKIP",
  };
}

  function routeTarget(npc, step2) {
    // LOCKED FIRST-YES-WINS EXPLICIT-ONLY
    // RelationshipEngine is conservative: only disposition-relevant actions route.
    // Directly affected NPCs and AffectedObservers may change.
    // ACTION_KIND set from Step 2:
    // Intimate_Advance, Stealth, Melee, Ranged, Magic, Intimidate, Bluff, Diplomacy, Athletics, Survival, Normal_Interaction

    const isDirect = step2.ActionTargets.includes(npc.name);
    const isOpp = step2.OppTargets.includes(npc.name);
    const isAffectedObserver = step2.AffectedObservers.includes(npc.name);
    const benefit = impactOnNpcExplicit(npc, step2) === "BENEFIT";
    const harm = impactOnNpcExplicit(npc, step2) === "HARM";
    const landed = step2.LandedActions > 0;
    const k = step2.ACTION_KIND;

    if (!isDirect && !isAffectedObserver) return "No Change";

    if (!isDirect && isAffectedObserver) {
      if (benefit) return "Bond";
      if (harm) return "Hostility";
      return "No Change";
    }

    if (k === "Normal_Interaction") return "No Change";

    if (k === "Diplomacy") return landed ? "Bond" : "No Change";

    if (k === "Bluff") return landed ? "No Change" : "Bond";

    if (k === "Intimidate") return landed && isOpp ? "Fear" : "Hostility";

    if (k === "Intimate_Advance") {
      return consentExplicit() ? "Bond" : (intimacyOverrideExplicit() !== "NONE" ? "No Change" : "Hostility");
    }

    if (k === "Stealth") {
      // Friendly target: no disposition shift.
      if (stats.B >= 3 && stats.H <= 2) return "No Change";
      // Neutral / opposed / suspicious target: hostile reaction on discovery.
      return "Hostility";
    }


    if (k === "Athletics" || k === "Survival") {
      return benefit ? "Bond" : "No Change";
    }

    if (k === "Melee" || k === "Ranged" || k === "Magic") {
      return isDirect ? "Hostility" : "No Change";
    }

    return "No Change";
  }

  function auditInteraction(npc, step2) {
    // LOCKED EXPLICIT-ONLY
    // Audit gates Bond growth only.
    // Meaningfulness = user-risk + NPC benefit.
    const RISK = riskExplicit() ? "Y" : "N";
    const NPC_STAKES = (impactOnNpcExplicit(npc, step2) === "BENEFIT") ? "Y" : "N";
    const Count = (RISK === "Y") + (NPC_STAKES === "Y");
    return {
      Class: Count === 0 ? "SHALLOW" : (Count === 1 ? "SUBSTANTIVE" : "MEANINGFUL"),
      Count,
      RISK,
      NPC_STAKES
    };
  }

  function deriveDirection(target, audit, stats, step2) {
    // LOCKED
    // No Change or SHALLOW -> no delta.
    // Fear / Hostility reduce Bond and raise their own track.
    // Bond can raise or lower Bond depending on action outcome.
    if (target === "No Change" || audit.Class === "SHALLOW") return { b: 0, f: 0, h: 0 };

    if (target === "Fear" || target === "Hostility") {
      return { b: -1, f: target === "Fear" ? 1 : 0, h: target === "Hostility" ? 1 : 0 };
    }

    if (target === "Bond" && step2.ACTION_KIND === "Bluff" && step2.LandedActions === 0) {
      return { b: -1, f: 0, h: 0 };
    }

    const meaningful = audit.Class === "MEANINGFUL";
    return {
      b: (stats.B <= 2) ? 1 : (stats.B === 3 ? (meaningful ? 1 : 0) : 0),
      f: ((stats.F === 4 && meaningful) || stats.F === 3) ? -1 : 0,
      h: ((stats.H === 4 && meaningful) || stats.H === 3) ? -1 : 0,
    };
  }

  function updateDisposition(stats, d) {
    // LOCKED
    const clamp = (v) => Math.max(1, Math.min(4, v));
    stats.B = clamp(stats.B + d.b);
    stats.F = clamp(stats.F + d.f);
    stats.H = clamp(stats.H + d.h);
    if (stats.F === 4 || stats.H === 4) stats.B = 1;
    return stats;
  }

  function classifyDisposition(stats) {
    // LOCKED
    const lock =
      stats.F === 4 ? "TERROR" :
      stats.H === 4 ? "HATRED" :
      (stats.F === 3 || stats.H === 3) ? "FREEZE" : "None";
    const behavior =
      lock !== "None" ? lock :
      stats.B === 4 ? "CLOSE" :
      stats.B === 3 ? "FRIENDLY" :
      stats.B === 2 ? "NEUTRAL" : "BROKEN";
    return { lock, behavior };
  }

  function checkThreshold(stats) {
    // LOCKED
    const LockActive = (stats.F >= 3 || stats.H >= 3) ? "Y" : "N";
    const Override = intimacyOverrideExplicit();
    return { LockActive, OverrideActive: Override !== "NONE" ? "Y" : "N", Override };
  }

  const target = routeTarget(npc, step2);
  const audit = auditInteraction(npc, step2);
  updateDisposition(stats, deriveDirection(target, audit, stats, step2));
  const disp = classifyDisposition(stats);
  const threshold = checkThreshold(stats);

  return {
    NPC: npc.name,
    FinalState: `B${stats.B}/F${stats.F}/H${stats.H}`,
    Lock: disp.lock,
    Behavior: disp.behavior,
    Target: target,
    Landed: step2.LandedActions > 0 ? "Y" : "N",
    OutcomeTier: step2.OutcomeTier || "NONE",
    NarrationBand: step2.NarrationBand || "standard",
    IntimacyGate:
      (threshold.LockActive === "Y") ? "DENY" :
      consentExplicit() ? "ALLOW" :
      (threshold.OverrideActive === "Y") ? "ALLOW" :
      (stats.B >= 4) ? "ALLOW" : "SKIP",
  };
}

