function ResolutionEngine(input) {
  const DEF = Object.freeze({
    STATS:
'PWR:"Strength,Melee,Grappling,Endurance,Physical Resistance,Athletics", AGI:"Dexterity,Ranged,Dodge,Stealth,Precision,Reflexes", MND:"Intelligence,Perception,Willpower,Tech,Magic,Notice,Discipline,Survival", CHA:"Persuasion,Deception,Presence,Charm,Social Force".',
    UNIVERSAL:
'LOCKED UNIVERSAL RULES: EXPLICIT-ONLY. FIRST-YES-WINS. Match by meaning/intent, not exact wording. Examples/phrases inside functions are semantic anchors, not required literal text. Prefer decisive goal-directed action over setup/movement/flourish. Ordinary banter, compliments, greetings, thanks, casual flirting, and harmless social flavor are FREEFORM unless there is an explicit ask, persuasion attempt, deception, coercion, or other clear influence goal. TIE=DEFENDER/OPPOSITION WINS. NEVER INVENT STATS/TARGETS/ACTIONS. MAX 3 ACTIONS. If no bucket clearly applies, return FREEFORM:Normal_Interaction.',
    CORE_STATS:
'ANCHOR CALL: Read most recent sceneTracker. Under exact NPC entry, read line starting "currentCoreStats:". Return PWR[x]/AGI[y]/MND[z]/CHA[w]. If found -> use. Else -> generateStats(npc) once and let sceneTracker() save. NEVER re-roll/invent.',
    CONSENT:
'CONSENT=Y ONLY if explicit affirmative consent is present in-scene or clearly established beforehand. Attraction, teasing, flirtation, silence, lack of resistance, or prior roll success do NOT equal consent. Uncertain = N.',
    PREDETERMINED:
'PREDETERMINED=Y ONLY if the outcome is explicitly fixed by lore, card text, scene text, or tracker. Do not infer inevitability from tone or archetype. Uncertain = N.'
  });

  function actionCount(input) {
    // LOCKED FIRST-YES-WINS EXPLICIT-ONLY (repeats duplicate a1; distinct sequences create a2/a3)
    const lower = input.toLowerCase();
    if (/three times|three attacks|3x/i.test(lower)) return ["a1","a1","a1"];
    if (/twice|two times|2x/i.test(lower)) return ["a1","a1"];
    if (/then|and then|follow with|finish with|before that|after that|first.*then|resolves into|shift.*into|cut and .*strike|grip change .*strike|as i turn .*strike|motion resolves into/i.test(lower)) return ["a1","a2"];
    return ["a1"];
  }

  function classifyAction(input) {
    // LOCKED FIRST-YES-WINS EXPLICIT-ONLY; match by meaning, prefer decisive clause, freeform examples follow
    const lower = input.toLowerCase();
    const focus = /then|and then|follow with|finish with|after that|resolves into|motion resolves into/i.test(lower)
      ? lower.split(/then|and then|follow with|finish with|after that|resolves into|motion resolves into/i).pop().trim()
      : lower;

    if (/kiss|grope|intimate touch|advance intimately|forceful embrace/i.test(focus)) return { TYPE:"COMBAT", ACTION_KIND:"Intimate_Advance" };
    if (/sneak|stealth|hide|slip past|avoid detection|avoid notice|remain unseen|stay hidden/i.test(focus)) return { TYPE:"COMBAT", ACTION_KIND:"Stealth" };
    if (/punch|slash|grapple|strike|swing|melee|harm|restrain|stab|kick|tackle|shove/i.test(focus)) return { TYPE:"COMBAT", ACTION_KIND:"Melee" };
    if (/shoot|arrow|throw|bow|gun|ranged|crossbow|fire/i.test(focus)) return { TYPE:"COMBAT", ACTION_KIND:"Ranged" };
    if (/cast spell|magic attack|spell|hex|curse|fireball|lightning/i.test(focus)) return { TYPE:"COMBAT", ACTION_KIND:"Magic" };
    if (/threaten|coerce|intimidate|insult|fuck you|power display|bully|warning aimed at compliance|drop it or|do it or else/i.test(focus)) return { TYPE:"SOCIAL", ACTION_KIND:"Intimidate" };
    if (/lie|deceive|bluff|misdirect|fake|pretend|trick|mislead/i.test(focus)) return { TYPE:"SOCIAL", ACTION_KIND:"Bluff" };
    if (/negotiate|persuade|convince|appeal|plead|bargain|request|ask .* out|date me|go out with me|i love you|confess/i.test(focus)) return { TYPE:"SOCIAL", ACTION_KIND:"Diplomacy" };
    if (/climb|swim|jump|break door|lift|push|run|athletic|physical feat|force gate|hold up|drag/i.test(focus)) return { TYPE:"SKILL", ACTION_KIND:"Athletics" };
    if (/forage|track|navigate|start fire|scout|fieldcraft|survival|practical task|utility|set camp|read terrain/i.test(focus)) return { TYPE:"SKILL", ACTION_KIND:"Survival" };
    if (/banter|small talk|chat|talk|conversation|compliment|you look nice|beautiful|pretty|handsome|greet|hello|hi|hey|thank|thanks|casual flirt|tease|teasing|joke|laugh|smile|wave|nod/i.test(focus)) {
      return { TYPE:"FREEFORM", ACTION_KIND:"Normal_Interaction" };
    }
    return { TYPE:"FREEFORM", ACTION_KIND:"Normal_Interaction" };
  }

  function determineOpposition(classified) {
    // LOCKED: Social/combat opposed, skill DC vs environment, freeform none
    if (classified.TYPE === "SOCIAL") return { targetType:"living", mode:"OPPOSED" };
    if (classified.TYPE === "COMBAT") return { targetType:"living", mode:"OPPOSED" };
    if (classified.TYPE === "SKILL") return { targetType:"env", mode:"DC" };
    return { targetType:"none", mode:"NONE" };
  }

  function identifyAffectedObservers(input, actionTargets, oppTargets) {
    // LOCKED EXPLICIT-ONLY: list named NPCs not in targets/opponents but explicitly benefited/affected
  }

  function mapStats(input, classified) {
    // LOCKED stat mappings
    const lower = input.toLowerCase();
    let dc = 13;
    if (/easy|routine|simple|open|unsecured/i.test(lower)) dc = 10;
    else if (/hard|difficult|challenging|guarded|sturdy/i.test(lower)) dc = 16;
    else if (/extreme|impossible|masterwork|fortified|sealed/i.test(lower)) dc = 20;

    if (classified.ACTION_KIND === "Normal_Interaction") return { userStat:null };
    if (["Diplomacy","Bluff","Intimidate"].includes(classified.ACTION_KIND)) return { userStat:"CHA", oppStat:"MND" };
    if (classified.ACTION_KIND === "Athletics") return { userStat:"PWR", dcValue:dc };
    if (classified.ACTION_KIND === "Survival") return { userStat:"MND", dcValue:dc };
    if (classified.ACTION_KIND === "Stealth") return { userStat:"AGI", oppStat:"MND" };
    if (classified.ACTION_KIND === "Intimate_Advance") return { userStat:"AGI", oppStat:"AGI" };
    if (["Melee","Ranged","Magic"].includes(classified.ACTION_KIND)) {
      const oppStat = /block|brace|parry|grapple back|resist with force|physically contest|raise shield|deflect/i.test(lower) ? "PWR" : "AGI";
      if (classified.ACTION_KIND === "Melee") return { userStat:"PWR", oppStat };
      if (classified.ACTION_KIND === "Ranged") return { userStat:"AGI", oppStat };
      if (classified.ACTION_KIND === "Magic") return { userStat:"MND", oppStat };
    }
    return { userStat:null };
  }

  function consentEstablished(input) {
    // LOCKED EXPLICIT-ONLY consent detection
    const lower = input.toLowerCase();
    return /with consent|consensual|they consent|she consents|he consents|they agreed|she agreed|he agreed|welcomed kiss|invited kiss|explicitly invited|explicitly allowed/i.test(lower);
  }

  function outcomePredetermined(input) {
    // LOCKED EXPLICIT-ONLY predetermined check
    const lower = input.toLowerCase();
    return /predetermined|pre-decided|already decided|automatic success|automatic failure|fated|guaranteed by lore|fixed outcome/i.test(lower);
  }

  function rollTrigger(classified, input) {
    // LOCKED ROLL|SKIP (FREEFORM skip, consent only for Intimate_Advance, predetermined skip)
    if (classified.TYPE === "FREEFORM") return "SKIP";
    if (classified.ACTION_KIND === "Intimate_Advance" && consentEstablished(input)) return "SKIP";
    if (outcomePredetermined(input)) return "SKIP";
    return "ROLL";
  }

  function getCoreStats(npc) {
    // per DEF.CORE_STATS
  }

  function generateStats(target) {
    // LOCKED stat generation (tier/role/distribution)
  }

  function resolveMargin(userTot, oppTot, actions) {
    // LOCKED outcome tiers + multi-action
    const margin = userTot - oppTot;
    let OutcomeTier = "MINOR_FAILURE", LandedActions = 0;
    if (margin >= 8) { OutcomeTier = "CRITICAL_SUCCESS"; LandedActions = 3; }
    else if (margin >= 5) { OutcomeTier = "MODERATE_SUCCESS"; LandedActions = 2; }
    else if (margin >= 1) { OutcomeTier = "MINOR_SUCCESS"; LandedActions = 1; }
    else if (margin >= -3) { OutcomeTier = "MINOR_FAILURE"; }
    else if (margin >= -7) { OutcomeTier = "MODERATE_FAILURE"; }
    else { OutcomeTier = "CRITICAL_FAILURE"; }
    LandedActions = Math.min(LandedActions, actions.length);
    return { Margin: margin, OutcomeTier, LandedActions };
  }

  function getNarrationBand(TYPE, OutcomeTier) {
    if (TYPE === "FREEFORM") return "no_roll";
    if (TYPE === "SKILL") {
      if (OutcomeTier === "MINOR_SUCCESS") return "success_with_cost_or_instability";
      if (OutcomeTier === "MODERATE_SUCCESS") return "clean_success";
      if (OutcomeTier === "CRITICAL_SUCCESS") return "exceptional_success_or_momentum";
      if (OutcomeTier === "MINOR_FAILURE") return "failure_with_mitigation";
      if (OutcomeTier === "MODERATE_FAILURE") return "failure_with_setback";
      if (OutcomeTier === "CRITICAL_FAILURE") return "catastrophic_failure";
    }
    if (TYPE === "SOCIAL") {
      if (OutcomeTier === "MINOR_SUCCESS") return "slight_shift_or_hesitation";
      if (OutcomeTier === "MODERATE_SUCCESS") return "meaningful_influence";
      if (OutcomeTier === "CRITICAL_SUCCESS") return "major_concession_or_strong_shift";
      if (OutcomeTier === "MINOR_FAILURE") return "no_gain";
      if (OutcomeTier === "MODERATE_FAILURE") return "resistance_or_refusal";
      if (OutcomeTier === "CRITICAL_FAILURE") return "complete_refusal_or_rejection";
    }
    if (TYPE === "COMBAT") {
      if (OutcomeTier === "MINOR_SUCCESS") return "light_hit_or_small_opening";
      if (OutcomeTier === "MODERATE_SUCCESS") return "solid_hit_or_clear_advantage";
      if (OutcomeTier === "CRITICAL_SUCCESS") return "dominant_exchange_or_overwhelming_hit";
      if (OutcomeTier === "MINOR_FAILURE") return "checked_or_bare_miss";
      if (OutcomeTier === "MODERATE_FAILURE") return "punished_opening_or_loss_of_position";
      if (OutcomeTier === "CRITICAL_FAILURE") return "severe_reversal_or-devastating_counter";
    }
    return "standard";
  }

  const actions = actionCount(input);
  const classified = classifyAction(input);
  const trig = rollTrigger(classified, input);
  if (trig === "SKIP") {
    const targets = [];
    return { TYPE: classified.TYPE, actions, ACTION_KIND: classified.ACTION_KIND, LandedActions:0, OutcomeTier:"NONE", NarrationBand:"no_roll", ActionTargets:targets, OppTargets:["(none)"], AffectedObservers:["(none)"] };
  }
  const opposition = determineOpposition(classified);
  const stats = mapStats(input, classified);
  // actual roll path omitted for brevity—COT handles dice & totals
}

