function CHAOS_INTERRUPT(step2Handoff, step3Handoffs, sceneSummary, diceList) {
  // LOCKED PROTOCOL (VIOLATION=INSTANT FAIL): SINGLE-PASS; FIRST-YES-WINS; STOP-ON-RETURN; EXPLICIT-ONLY (Uncertain→NO). ROLL ECONOMY: consume next 5 dice strictly; resets per {{user}} msg. OUTPUT IN COT STEP 4: EXACTLY labeled lines ONLY. NO prose/gate lists/dice-history/“Wait/Actually/Hmm/...”. Simulate rules only.
  // ULTIMATE ANTI-DRIFT (VIOLATION=INSTANT FAIL): Call ONLY named functions. NEVER re-roll/reconsider/infer/hedge/chain. MUST reveal Anchor+Vector in text. Vividness: ≥1 sensory detail + ≥1 immediate consequence. Exactly 2–3 sentences: INTRO→IMPACT→CHOICE(optional). BANS: no alternatives/hedging; ONE EVENT ONLY; Use Step2/Step3 as truth.
  // NUCLEAR DICE LOCK: 5 literal values. Sequential shift(). NEVER invent.
  // ctx: PUBLIC if NPC LIST ≥2 (non-party) OR sceneSummary has public/crowded/open/market/tavern/street/square etc.; else ISOLATED.

  let A = diceList.shift(), O = diceList.shift(), I = diceList.shift();
  const npcCount = step3Handoffs ? step3Handoffs.length : 0;
  const ctx = (npcCount >= 2 || /public|crowd|open|market|tavern|street|square/i.test(sceneSummary)) ? "PUBLIC" : "ISOLATED";

if (A < 17) return {CHAOS: {triggered: false, band: "None", magnitude: "None", anchor: "None", vector: "None", personVector: false, fullText: null}};

  let band = O <= 5 ? "HOSTILE" : O <= 14 ? "COMPLICATION" : "BENEFICIAL";
  let magnitude = (O === 1 || O === 20) ? "EXTREME" : (O <= 2 || O >= 19) ? "MAJOR" : (O <= 4 || O >= 17) ? "MODERATE" : "MINOR";

  const ANCHORS = ["GOAL","ENVIRONMENT","KNOWN_NPC","RESOURCE","CLUE"];
  const anchor = ANCHORS[diceList.shift() % 5];

  let vectors = ctx === "PUBLIC" ? ["NPC","CROWD","AUTHORITY","ENVIRONMENT","SYSTEM"] : (I >= 17 ? ["ENVIRONMENT","SYSTEM","ENTITY"] : ["ENVIRONMENT","SYSTEM"]);
  const vector = vectors[diceList.shift() % vectors.length];
  const personVector = (vector === "NPC" || vector === "AUTHORITY");

  RETURN HANDOFF {CHAOS: {triggered: true, band, magnitude, anchor, vector, personVector}};
}

