// NPCProactivityEngine v3-compact (1 die per NPC; intent categories; minimal drift)
// Outputs: {NPC:{Proactive:[Y/N], Intent:[...], Impulse:[ANGER|FEAR|BOND]}} only.
// Rendering is handled by Step 4.3e (contextual concrete action consistent with Intent).
function NPCProactivityEngine(npcHandoffList, step2, chaosHandoff, diceBudget) {
  const results = {};
  const k = step2.ACTION_KIND || "OTHER";
  const landed = step2.LandedActions || 0;
  const chaosBand = (chaosHandoff && chaosHandoff.triggered) ? chaosHandoff.band : "None";
  const cap = npcHandoffList.length <= 3 ? 1 : npcHandoffList.length <= 6 ? 2 : 3;

  const hostile  = new Set(["INSULT","ATTACK_PHYSICAL","BETRAYAL","HARM_THIRD_PARTY"]);
  const coercive = new Set(["INTIMIDATE","THREATEN","POWER_DISPLAY"]);
  const friendly = new Set(["NEUTRAL_SOCIAL","HELP_PROTECT"]);
  const romance  = new Set(["ROMANCE_VERBAL","ROMANCE_PHYSICAL"]);

  function parseFS(fs) { const m=/^B(\d)\/F(\d)\/H(\d)$/.exec(fs||""); return m?{B:+m[1],F:+m[2],H:+m[3]}:{B:2,F:2,H:2}; }
  function lockFrom(s){ return s.F===4?"TERROR":s.H===4?"HATRED":(s.F===3||s.H===3)?"FREEZE":"None"; }
  function thr(pp){ return pp<=0?21:pp===1?18:pp===2?15:pp===3?12:10; } // pp 0-4+

  const cand = [];
  for (const h of npcHandoffList) {
    const die = diceBudget.shift();
    const cur = parseFS(h.Current);
    const fin = parseFS(h.FinalState);
    const Lock = h.Lock || lockFrom(fin);
    const Class = h.Class || "SHALLOW";
    const Target = h.Target || "No Change";
    const IntimacyGate = h.IntimacyGate || "SKIP";
    const Override = h.Override || "NONE";

    // ---- Impulse (simple) ----
    let impulse = "BOND";
    if (Lock === "HATRED") impulse = "ANGER";
    else if (Lock === "TERROR") impulse = "FEAR";
    else if (hostile.has(k)) impulse = "ANGER";
    else if (coercive.has(k)) impulse = "FEAR";
    else if (romance.has(k) && IntimacyGate === "DENY") impulse = "ANGER";
    else if (friendly.has(k)) impulse = "BOND";
    else {
      const max = Math.max(fin.H, fin.F, fin.B);
      impulse = (max===fin.H)?"ANGER":(max===fin.F)?"FEAR":"BOND";
    }

    // ---- Proactivity pressure (pp 0-4) ----
    let pp = 0;
    if (Class !== "SHALLOW") pp += 1;
    if (Lock !== "None") pp += 1;
    if (lockFrom(cur) === "None" && lockFrom(fin) !== "None") pp += 1; // crossed into FREEZE/TERROR/HATRED
    if (chaosBand !== "None") pp += 1;
    if (Target !== "No Change" || landed > 0) pp += 1;
    if (pp > 4) pp = 4;
    if (Class === "SHALLOW" && Target === "No Change" && chaosBand === "None") pp = 0;

    const passes = (die >= thr(pp));

    // ---- Intent (category; contextual rendering later) ----
    let intent = "NONE";
    if (passes) {
      if (impulse === "ANGER") {
        if (romance.has(k) && IntimacyGate === "DENY") intent = "BOUNDARY_PHYSICAL";
        else if (k === "ATTACK_PHYSICAL" || fin.H >= 4) intent = "ESCALATE_VIOLENCE";
        else intent = "THREAT_OR_POSTURE";
      } else if (impulse === "FEAR") {
        if (fin.F >= 4) intent = "CALL_HELP_OR_AUTHORITY";
        else intent = "WITHDRAW_OR_BOUNDARY";
      } else { // BOND
        const allow = (IntimacyGate === "ALLOW" || Override !== "NONE") && fin.B >= 3;
        if (allow) intent = "INTIMACY_OR_FLIRT";
        else if (k === "HELP_PROTECT") intent = "SUPPORT_ACT";
        else intent = "PLAN_OR_BANTER";
      }
    }

    results[h.NPC] = { Proactive:"N", Intent:"NONE", Impulse:impulse };
    if (passes) cand.push({NPC:h.NPC, die, intent, impulse});
  }

  cand.sort((a,b)=>b.die-a.die);
  for (let i=0; i<Math.min(cap, cand.length); i++) {
    const c = cand[i];
    results[c.NPC] = { Proactive:"Y", Intent:c.intent, Impulse:c.impulse };
  }
  return results;
}
